INSERT INTO lessons (id, unit_id, category_id, position, title_en, title_fr, objectives_en, objectives_fr, difficulty, created_at) VALUES
  ('bf08eabb-6d0b-4598-bdcd-055d9b1f587f', '3a462949-cdb5-4ee4-bf6b-f8aa0a1f2e25', '8e4d6e59-4b0a-4ad5-bbdf-10b98f9bc011', 1, 'Personal Pronouns & Usage', 'Pronoms personnels et usage', '["Master subject pronouns (I, you, he/she, we, you pl., they).", "Use pronouns in simple declarative and interrogative sentences.", "Practice pronoun agreement with verbs."]'::jsonb, '["Maîtriser les pronoms sujets (je, tu, il/elle, nous, vous, ils).", "Utiliser les pronoms dans des phrases déclaratives et interrogatives simples.", "S’exercer à l’accord des pronoms avec les verbes."]'::jsonb, 'Beginner', '2025-09-17T12:19:51.286065+00:00'),
  ('c4d1ec7f-d19f-4703-b267-8c7641d5d301', '4a199f66-b0cf-40b0-b6a7-a77e400b2a50', 'b846a053-92a3-4b46-aa5f-50ac0c7024ba', 1, 'Greetings and Introductions', 'Salutations et présentations', '["Use common greeting formulas for different times of day.", "Introduce yourself: name, origin, and simple background info.", "Practice short dialogues for meeting people."]'::jsonb, '["Utiliser les formules de salutation selon le moment de la journée.", "Se présenter : nom, origine, et quelques infos basiques.", "S’exercer sur de courts dialogues pour rencontrer des gens."]'::jsonb, 'Beginner', '2025-09-17T12:19:51.286065+00:00'),
  ('3a700869-d6ad-434c-880f-9eb04c3a3d4b', 'fb91fd76-ed39-4c39-99aa-81278a36e0a0', '8e4d6e59-4b0a-4ad5-bbdf-10b98f9bc011', 1, 'Comparatives & Superlatives', 'Comparatifs et superlatifs', '["Form comparative and superlative structures.", "Use adjectives with correct agreement and intensity markers.", "Compare people, places, and things in context."]'::jsonb, '["Former les structures comparatives et superlatives.", "Utiliser les adjectifs avec l’accord correct et marqueurs d’intensité.", "Comparer personnes, lieux et choses en contexte."]'::jsonb, 'Intermediate', '2025-09-17T12:19:51.286065+00:00'),
  ('31c643db-3a8d-4f7f-9cda-51ae1baf45ab', '52a59643-5198-48ff-ac2f-1cf141d3bb49', '8e4d6e59-4b0a-4ad5-bbdf-10b98f9bc011', 1, 'Present Tense: Conjugation & Use', 'Présent : conjugaison et usage', '["Conjugate common verbs in present tense for all persons.", "Make simple statements about habitual actions.", "Use time markers to indicate present routines."]'::jsonb, '["Conjuguer des verbes courants au présent pour toutes les personnes.", "Faire des affirmations simples sur des actions habituelles.", "Utiliser des marqueurs temporels pour indiquer les routines présentes."]'::jsonb, 'Beginner', '2025-09-17T12:19:51.286065+00:00'),
  ('3b732d48-bba6-458e-9c86-da8414f73b69', '42dfd6bd-a33d-419b-9b9b-b149bccefc1e', '99214817-cd46-4111-8057-40e9dc9a616d', 1, 'Alphabet and Sounds', 'Alphabet et sons', '["Learn the Kabiyè alphabet letters and special characters.", "Recognize consonant clusters and unique consonants (kp, gb, ɖ, ŋ).", "Practice basic syllable structure and pronunciation patterns."]'::jsonb, '["Apprendre les lettres de l’alphabet kabiyè et les caractères spéciaux.", "Reconnaître les groupes de consonnes et les consonnes spécifiques (kp, gb, ɖ, ŋ).", "Exercer la structure syllabique de base et les schémas de prononciation."]'::jsonb, 'Beginner', '2025-09-17T12:19:51.286065+00:00'),
  ('aac0286f-e376-4bba-9ccc-9bd89a136db6', '30ec7c7a-671f-4d25-b0db-a796963b8a7e', '99214817-cd46-4111-8057-40e9dc9a616d', 1, 'Numbers 1–20', 'Nombres 1–20', '["Count from 1 to 20 and say simple quantities.", "Use numbers in short phrases (age, quantity).", "Practice pronunciation of numbers and listening comprehension."]'::jsonb, '["Compter de 1 à 20 et dire des quantités simples.", "Utiliser les nombres dans des phrases courtes (âge, quantité).", "S’exercer à la prononciation des nombres et à la compréhension orale."]'::jsonb, 'Beginner', '2025-09-17T12:19:51.286065+00:00'),
  ('f5b4956e-6c9a-4efb-ac63-31a8fbcd304a', '4d891f0b-f326-4257-af60-e4b4369e0c50', 'b846a053-92a3-4b46-aa5f-50ac0c7024ba', 1, 'Family Members & Kinship', 'Membres de la famille et parenté', '["Name immediate family members (mother, father, siblings).", "Understand kinship terms for extended family (uncles, cousins).", "Describe simple family relationships."]'::jsonb, '["Nommer les membres de la famille proche (mère, père, frères/sœurs).", "Comprendre les termes de parenté pour la famille élargie (oncles, cousins).", "Décrire des relations familiales simples."]'::jsonb, 'Beginner', '2025-09-17T12:19:51.286065+00:00'),
  ('1720c145-399c-46e5-8f80-e63b5f14cd66', '899b1475-038b-4364-8ec7-a7ce6b9a2c3c', 'd8725dff-4eec-4358-8ac3-8c8b0129d69a', 1, 'Traditional Food & Cooking', 'Cuisine traditionnelle et gastronomie', '["Learn names of iconic local dishes and ingredients.", "Describe cooking methods and cultural contexts for meals.", "Practice dialogues about recipes and sharing food."]'::jsonb, '["Apprendre les noms de plats locaux emblématiques et ingrédients.", "Décrire les méthodes de cuisson et contextes culturels des repas.", "S’exercer sur des dialogues concernant recettes et partage de repas."]'::jsonb, 'Intermediate', '2025-09-17T12:19:51.286065+00:00'),
  ('5f8aa628-8f93-4f8f-918e-89b7cd4f7d12', '845d3a5d-bc04-4004-b7b2-151ce4f47c1f', 'b846a053-92a3-4b46-aa5f-50ac0c7024ba', 1, 'Food Basics: Staples & Ingredients', 'Alimentation de base : produits et ingrédients', '["Name common staple foods (e.g., cassava, maize, rice).", "Identify ingredients used in local dishes.", "Use vocabulary in short cooking or shopping phrases."]'::jsonb, '["Nommer les aliments de base courants (ex. manioc, maïs, riz).", "Identifier les ingrédients utilisés dans les plats locaux.", "Utiliser le vocabulaire dans de courtes phrases de cuisine ou d’achat."]'::jsonb, 'Beginner', '2025-09-17T12:19:51.286065+00:00'),
  ('4c325639-7f58-470f-b87a-93ec21ce182b', '560783da-e5c0-4ae8-8036-ed4cf767a808', 'd6606da8-765d-490b-ab4c-1b0246140547', 1, 'Body Parts & Basic Health', 'Parties du corps et notions de santé de base', '["Name key body parts and basic anatomy vocabulary.", "Describe simple symptoms (ache, fever, cut).", "Use phrases to say you feel well/ill."]'::jsonb, '["Nommer les principales parties du corps et le vocabulaire d’anatomie de base.", "Décrire des symptômes simples (douleur, fièvre, coupure).", "Utiliser des phrases pour dire que vous vous sentez bien/mal."]'::jsonb, 'Beginner', '2025-09-17T12:19:51.286065+00:00'),
  ('b8150724-2782-4120-b7dc-5049ef1711a5', '1a18365e-9c01-4460-a342-fa982e1194df', 'd6606da8-765d-490b-ab4c-1b0246140547', 1, 'Professions & Jobs', 'Professions et emplois', '["Name common professions and describe job duties.", "Ask and answer questions about someone’s work.", "Use workplace vocabulary in short sentences."]'::jsonb, '["Nommer des professions courantes et décrire les tâches.", "Poser et répondre à des questions sur le travail de quelqu’un.", "Utiliser le vocabulaire professionnel dans des phrases courtes."]'::jsonb, 'Intermediate', '2025-09-17T12:19:51.286065+00:00'),
  ('212addb2-a84c-4cb4-8419-b925e15de715', 'b1832ae2-eb98-4d05-91e5-6a5da0948827', '6b12c499-4ee6-47e8-9b69-0328cad08c03', 1, 'Asking for Directions', 'Demander son chemin', '["Ask where places are using landmarks and directions.", "Understand simple directional replies and distances.", "Practice polite ways to ask for clarification."]'::jsonb, '["Demander où se trouvent des lieux en utilisant des repères et directions.", "Comprendre des réponses directionnelles simples et les distances.", "Pratiquer des manières polies de demander des précisions."]'::jsonb, 'Beginner', '2025-09-17T12:19:51.286065+00:00'),
  ('2bb5d175-caf4-477a-b43b-f7838a6fa005', 'f6b6bc21-877c-48f8-9d89-f57f12e3394e', 'b846a053-92a3-4b46-aa5f-50ac0c7024ba', 1, 'Shopping Basics: Goods & Services', 'Bases des achats : biens et services', '["Identify common goods and services in shops and markets.", "Ask availability and make simple purchases.", "Practice polite transactional phrases."]'::jsonb, '["Identifier les biens et services courants dans les magasins et marchés.", "Demander la disponibilité et effectuer des achats simples.", "Pratiquer des phrases transactionnelles polies."]'::jsonb, 'Beginner', '2025-09-17T12:19:51.286065+00:00'),
  ('16aa71fd-9e34-425f-9e52-64a3601b5d0f', '1a18365e-9c01-4460-a342-fa982e1194df', 'd6606da8-765d-490b-ab4c-1b0246140547', 2, 'School & Education Vocabulary', 'Vocabulaire scolaire et éducatif', '["Use vocabulary related to school, subjects, and learning.", "Talk about school activities and schedules.", "Describe a typical school day in simple terms."]'::jsonb, '["Utiliser le vocabulaire lié à l’école, aux matières et à l’apprentissage.", "Parler des activités scolaires et de l’emploi du temps.", "Décrire une journée scolaire typique en termes simples."]'::jsonb, 'Intermediate', '2025-09-17T12:19:51.286065+00:00'),
  ('9220417f-a886-446a-b8cf-62b8dea76712', '899b1475-038b-4364-8ec7-a7ce6b9a2c3c', 'd8725dff-4eec-4358-8ac3-8c8b0129d69a', 2, 'Ceremonies, Rites & Naming', 'Cérémonies, rites et nomination', '["Understand vocabulary related to important Kabiyè ceremonies.", "Learn naming customs and social roles in rites of passage.", "Discuss cultural meaning behind common rituals."]'::jsonb, '["Comprendre le vocabulaire lié aux cérémonies importantes kabiyè.", "Apprendre les coutumes de nomination et rôles sociaux dans les rites de passage.", "Discuter de la signification culturelle des rituels courants."]'::jsonb, 'Intermediate', '2025-09-17T12:19:51.286065+00:00'),
  ('b2b8f8a6-c35d-4b05-a59c-366a6800955e', 'f6b6bc21-877c-48f8-9d89-f57f12e3394e', 'b846a053-92a3-4b46-aa5f-50ac0c7024ba', 2, 'Phone & Messages', 'Téléphone et messages', '["Make and receive simple phone calls; leave messages.", "Use phone-specific phrases and numbers.", "Practice common short dialogues by phone."]'::jsonb, '["Passer et recevoir des appels simples ; laisser des messages.", "Utiliser des phrases et numéros spécifiques au téléphone.", "S’exercer sur des dialogues téléphoniques courts et fréquents."]'::jsonb, 'Intermediate', '2025-09-17T12:19:51.286065+00:00'),
  ('f7c33f37-64f3-4a1d-baa0-5bda7250bc39', 'fb91fd76-ed39-4c39-99aa-81278a36e0a0', '8e4d6e59-4b0a-4ad5-bbdf-10b98f9bc011', 2, 'Conjunctions & Complex Linking', 'Conjonctions et liaison complexe', '["Use coordinating and subordinating conjunctions to link ideas.", "Build complex sentences with multiple clauses.", "Practice logical connectors for cause, contrast and addition."]'::jsonb, '["Utiliser des conjonctions de coordination et subordination pour lier les idées.", "Construire des phrases complexes avec plusieurs propositions.", "S’exercer aux connecteurs logiques : cause, contraste, addition."]'::jsonb, 'Intermediate', '2025-09-17T12:19:51.286065+00:00'),
  ('949ef575-4f72-4b6b-9e9b-4f2256b23849', '845d3a5d-bc04-4004-b7b2-151ce4f47c1f', 'b846a053-92a3-4b46-aa5f-50ac0c7024ba', 2, 'Ordering & Meals: Restaurants & Home', 'Commander & repas : restaurants et à la maison', '["Order food and drinks in a market or simple restaurant.", "Describe what you like/dislike about meals.", "Practice polite requests and expressions for service."]'::jsonb, '["Commander nourriture et boissons au marché ou dans un restaurant simple.", "Décrire ce que vous aimez/n’aimez pas dans les repas.", "Pratiquer des demandes polies et expressions de service."]'::jsonb, 'Beginner', '2025-09-17T12:19:51.286065+00:00'),
  ('bc33b142-2390-46b7-b5a4-d186dfa7ebb6', '42dfd6bd-a33d-419b-9b9b-b149bccefc1e', '99214817-cd46-4111-8057-40e9dc9a616d', 2, 'Vowel Harmony and Length', 'Harmonie vocalique et longueur', '["Understand vowel harmony groups and their role in word formation.", "Differentiate short vs long vowels in pronunciation and meaning.", "Practice applying vowel harmony across simple words."]'::jsonb, '["Comprendre les groupes d’harmonie vocalique et leur rôle dans la formation des mots.", "Différencier les voyelles courtes et longues à l’oral et dans le sens.", "S’exercer à appliquer l’harmonie vocalique sur des mots simples."]'::jsonb, 'Beginner', '2025-09-17T12:19:51.286065+00:00'),
  ('3b4ca491-00b4-47e7-ac1d-c9bca1d4884b', '52a59643-5198-48ff-ac2f-1cf141d3bb49', '8e4d6e59-4b0a-4ad5-bbdf-10b98f9bc011', 2, 'Past Tense (Aorist): Completed Actions', 'Passé (aoriste) : actions accomplies', '["Learn aorist forms to express completed past events.", "Differentiate between simple past and past continuous (aspect).", "Practice short narratives in the past using common verbs."]'::jsonb, '["Apprendre les formes aoristes pour exprimer des événements passés accomplis.", "Différencier passé simple et passé continu (aspect).", "S’exercer sur de courtes narrations au passé avec des verbes courants."]'::jsonb, 'Intermediate', '2025-09-17T12:19:51.286065+00:00'),
  ('e91b44d9-d34f-4a97-8519-762b0b26d611', 'b1832ae2-eb98-4d05-91e5-6a5da0948827', '6b12c499-4ee6-47e8-9b69-0328cad08c03', 2, 'Transport Vocabulary & Tickets', 'Vocabulaire transport et billets', '["Name transport modes (taxi, moto, bus, train).", "Buy tickets and ask about schedules and fares.", "Use travel-related verbs and expressions."]'::jsonb, '["Nommer les modes de transport (taxi, moto, bus, train).", "Acheter des billets et demander horaires et tarifs.", "Utiliser des verbes et expressions liés au voyage."]'::jsonb, 'Beginner', '2025-09-17T12:19:51.286065+00:00'),
  ('83c147cc-8fa6-4027-afef-4fe28f613b48', '4a199f66-b0cf-40b0-b6a7-a77e400b2a50', 'b846a053-92a3-4b46-aa5f-50ac0c7024ba', 2, 'Politeness & Thanks', 'Politesse et remerciements', '["Use please, thank you, and sorry in natural contexts.", "Choose appropriate polite forms for elders and peers.", "Practice short exchanges requiring politeness."]'::jsonb, '["Utiliser s’il vous plaît, merci et désolé dans des contextes naturels.", "Choisir les formes de politesse adaptées aux aînés et pairs.", "S’exercer sur de courts échanges nécessitant la politesse."]'::jsonb, 'Beginner', '2025-09-17T12:19:51.286065+00:00'),
  ('2e1911ef-3356-42fe-b4ee-9d737cb122c4', '560783da-e5c0-4ae8-8036-ed4cf767a808', 'd6606da8-765d-490b-ab4c-1b0246140547', 2, 'At the Doctor / Health Clinic', 'Chez le médecin / clinique de santé', '["Explain symptoms to a health worker or doctor.", "Understand basic medical advice and prescriptions.", "Practice role-play: visiting a clinic and following recommendations."]'::jsonb, '["Expliquer des symptômes à un professionnel de santé ou médecin.", "Comprendre des conseils médicaux de base et des ordonnances.", "S’exercer par jeu de rôle : visite en clinique et suivi des recommandations."]'::jsonb, 'Intermediate', '2025-09-17T12:19:51.286065+00:00'),
  ('927c32e4-1615-45a8-9ef3-2ffdffd7f57b', '3a462949-cdb5-4ee4-bf6b-f8aa0a1f2e25', '8e4d6e59-4b0a-4ad5-bbdf-10b98f9bc011', 2, 'Possessive Pronouns & Possession', 'Pronoms possessifs et possession', '["Express ownership with correct possessive forms.", "Differentiate between my/your/his-her/our/their in common contexts.", "Practice sentences describing possession and belongings."]'::jsonb, '["Exprimer la possession avec les formes possessives correctes.", "Différencier mon/ton/son/son/ notre/leur dans des contextes courants.", "S’exercer sur des phrases décrivant la possession et les biens."]'::jsonb, 'Beginner', '2025-09-17T12:19:51.286065+00:00'),
  ('76ea258f-10e6-4d4a-8cd6-be8d5664b20a', '4d891f0b-f326-4257-af60-e4b4369e0c50', 'b846a053-92a3-4b46-aa5f-50ac0c7024ba', 2, 'Daily Routines & Common Verbs', 'Routines quotidiennes et verbes courants', '["Describe typical daily routines using common verbs.", "Use adverbs of frequency (always, often, sometimes).", "Practice present-tense verbs in sentences."]'::jsonb, '["Décrire des routines quotidiennes avec des verbes courants.", "Utiliser les adverbes de fréquence (toujours, souvent, parfois).", "S’exercer aux verbes au présent dans des phrases."]'::jsonb, 'Beginner', '2025-09-17T12:19:51.286065+00:00'),
  ('1b24f3d7-62e2-44a2-ae8b-aaca87a7156e', '30ec7c7a-671f-4d25-b0db-a796963b8a7e', '99214817-cd46-4111-8057-40e9dc9a616d', 2, 'Numbers up to 100', 'Nombres jusqu’à 100', '["Form tens and combine them with units to say numbers up to 100.", "Use numbers for prices and simple calculations.", "Practice listening and writing numbers in context."]'::jsonb, '["Former les dizaines et les combiner pour dire des nombres jusqu’à 100.", "Utiliser les nombres pour les prix et calculs simples.", "S’exercer à l’écoute et l’écriture des nombres en contexte."]'::jsonb, 'Beginner', '2025-09-17T12:19:51.286065+00:00'),
  ('b5441440-0948-4eba-a2bf-5a7e5b827302', '52a59643-5198-48ff-ac2f-1cf141d3bb49', '8e4d6e59-4b0a-4ad5-bbdf-10b98f9bc011', 3, 'Past Continuous & Aspectual Distinctions', 'Passé continu et distinctions d’aspect', '["Express ongoing past actions and interrupted events.", "Compare completed vs ongoing past actions using aspect markers.", "Use past continuous in storytelling contexts."]'::jsonb, '["Exprimer des actions passées en cours et des événements interrompus.", "Comparer actions passées accomplies vs en cours avec des marqueurs d’aspect.", "Utiliser le passé continu dans des contextes narratifs."]'::jsonb, 'Intermediate', '2025-09-17T12:19:51.286065+00:00'),
  ('713a8067-3b48-4ae0-b7b0-95ca31efd34b', '42dfd6bd-a33d-419b-9b9b-b149bccefc1e', '99214817-cd46-4111-8057-40e9dc9a616d', 3, 'Tones and Meaning', 'Tons et sens', '["Learn the two primary tone levels and tone marking conventions.", "Practice minimal pairs where tone changes meaning.", "Train listening and pronunciation of tonal contrasts."]'::jsonb, '["Apprendre les deux niveaux de tons principaux et la notation des tons.", "S’exercer sur des paires minimales où le ton change le sens.", "Entraîner l’écoute et la prononciation des contrastes tonals."]'::jsonb, 'Beginner', '2025-09-17T12:19:51.286065+00:00'),
  ('73a1bec5-f8ad-4885-ba06-900b5ae65800', '30ec7c7a-671f-4d25-b0db-a796963b8a7e', '99214817-cd46-4111-8057-40e9dc9a616d', 3, 'Dates & Calendar', 'Dates et calendrier', '["Name days of the week and months of the year.", "Say simple dates (day/month) and talk about birthdays/events.", "Use calendar vocabulary in practical sentences."]'::jsonb, '["Nommer les jours de la semaine et les mois de l’année.", "Dire des dates simples (jour/mois) et parler d’anniversaires/événements.", "Utiliser le vocabulaire du calendrier dans des phrases pratiques."]'::jsonb, 'Beginner', '2025-09-17T12:19:51.286065+00:00'),
  ('1c2e3ed5-3ee4-487e-8196-c67000f798b9', '4a199f66-b0cf-40b0-b6a7-a77e400b2a50', 'b846a053-92a3-4b46-aa5f-50ac0c7024ba', 3, 'Meeting New People: Questions & Answers', 'Rencontrer des personnes : questions et réponses', '["Ask and answer common introductory questions (where are you from, what do you do).", "Practice question words (who, what, where, when, why, how).", "Use short follow-up questions in dialogue."]'::jsonb, '["Poser et répondre aux questions d’introduction (d’où viens-tu, que fais-tu).", "S’exercer aux mots interrogatifs (qui, quoi, où, quand, pourquoi, comment).", "Utiliser des questions de relance courtes dans un dialogue."]'::jsonb, 'Beginner', '2025-09-17T12:19:51.286065+00:00'),
  ('73fe8c78-9f86-4404-993b-a60afea7805a', '4d891f0b-f326-4257-af60-e4b4369e0c50', 'b846a053-92a3-4b46-aa5f-50ac0c7024ba', 3, 'Weather & Seasons', 'Temps et saisons', '["Name weather conditions and seasonal vocabulary.", "Talk about typical weather for seasons and activities.", "Practice simple weather-related dialogues."]'::jsonb, '["Nommer les conditions météorologiques et le vocabulaire des saisons.", "Parler du temps typique selon les saisons et des activités.", "S’exercer sur de courts dialogues autour de la météo."]'::jsonb, 'Beginner', '2025-09-17T12:19:51.286065+00:00'),
  ('720de87d-1c76-40b7-8f3e-24c5cd746e33', '845d3a5d-bc04-4004-b7b2-151ce4f47c1f', 'b846a053-92a3-4b46-aa5f-50ac0c7024ba', 3, 'Market Interaction & Bargaining', 'Interaction au marché et négociation', '["Ask for prices and quantities at a market stall.", "Use bargaining phrases and respond to counter-offers.", "Practice dialogues that simulate buying and selling."]'::jsonb, '["Demander les prix et quantités à un étal de marché.", "Utiliser des phrases de négociation et répondre aux contre-offres.", "S’exercer sur des dialogues simulant l’achat et la vente."]'::jsonb, 'Beginner', '2025-09-17T12:19:51.286065+00:00'),
  ('5db4a75a-2c52-4037-8e19-f8f31bead52f', 'f6b6bc21-877c-48f8-9d89-f57f12e3394e', 'b846a053-92a3-4b46-aa5f-50ac0c7024ba', 3, 'Butcher & Meat Shop', 'Boucherie et magasin de viande', '["Order different types of meat", "Ask about meat cuts", "Discuss meat preparation"]'::jsonb, '["Commander différents types de viande", "Demander des coupes de viande", "Discuter de la préparation de la viande"]'::jsonb, 'Beginner', '2025-09-28T18:12:53.086673+00:00'),
  ('c4e2194d-3611-4635-9682-23c245ff018e', '3a462949-cdb5-4ee4-bf6b-f8aa0a1f2e25', '8e4d6e59-4b0a-4ad5-bbdf-10b98f9bc011', 3, 'Demonstratives: this & that', 'Démonstratifs : ceci et cela', '["Use demonstratives for near/far distinctions (this/that/these/those).", "Combine demonstratives with nouns in phrases.", "Practice pointing and describing objects in context."]'::jsonb, '["Utiliser les démonstratifs pour les distinctions proche/éloigné (ce/cet/ces).", "Combiner démonstratifs et noms dans des phrases.", "Pratiquer le geste & la description d’objets en contexte."]'::jsonb, 'Beginner', '2025-09-17T12:19:51.286065+00:00'),
  ('4b7dfbed-cf38-4be5-a22e-588bb7f5984a', 'fb91fd76-ed39-4c39-99aa-81278a36e0a0', '8e4d6e59-4b0a-4ad5-bbdf-10b98f9bc011', 3, 'Relative Clauses & Nominal Modification', 'Propositions relatives et modification nominale', '["Form relative clauses using who/which/that equivalents.", "Embed relative information to describe nouns more precisely.", "Practice transforming simple sentences into relative constructions."]'::jsonb, '["Former des propositions relatives utilisant les équivalents de qui/que/dont.", "Insérer des informations relatives pour décrire les noms plus précisément.", "S’exercer à transformer des phrases simples en constructions relatives."]'::jsonb, 'Advanced', '2025-09-17T12:19:51.286065+00:00'),
  ('dfca8148-c68b-4ce5-b0e7-e64eb0782fcb', '899b1475-038b-4364-8ec7-a7ce6b9a2c3c', 'd8725dff-4eec-4358-8ac3-8c8b0129d69a', 3, 'Proverbs, Idioms & Wisdom', 'Proverbes, idiomes et sagesse', '["Learn common Kabiyè proverbs and their literal/figurative meanings.", "Use idiomatic expressions in context to sound natural.", "Analyze proverbs and make cultural reflections in discussions."]'::jsonb, '["Apprendre des proverbes kabiyè courants et leurs sens littéral/figuratif.", "Utiliser des expressions idiomatiques en contexte pour paraître naturel.", "Analyser des proverbes et faire des réflexions culturelles lors de discussions."]'::jsonb, 'Advanced', '2025-09-17T12:19:51.286065+00:00'),
  ('043b3a55-2622-4d5d-89fb-b88c401864bc', '560783da-e5c0-4ae8-8036-ed4cf767a808', 'd6606da8-765d-490b-ab4c-1b0246140547', 3, 'General Practitioner & Primary Care', 'Médecin généraliste et soins primaires', '["Describe common symptoms", "Understand medical consultations", "Ask for medical advice"]'::jsonb, '["Décrire les symptômes courants", "Comprendre les consultations médicales", "Demander des conseils médicaux"]'::jsonb, 'Intermediate', '2025-09-28T18:12:31.587939+00:00'),
  ('13939fd8-1b88-44ee-9c4a-07ff2df51ea6', '1a18365e-9c01-4460-a342-fa982e1194df', 'd6606da8-765d-490b-ab4c-1b0246140547', 3, 'Office & Workplace Communication', 'Communication de bureau et lieu de travail', '["Discuss work schedules", "Handle workplace meetings", "Communicate with colleagues", "Describe work tasks"]'::jsonb, '["Discuter des horaires de travail", "Gérer les réunions de travail", "Communiquer avec les collègues", "Décrire les tâches de travail"]'::jsonb, 'Intermediate', '2025-09-28T18:13:28.423223+00:00'),
  ('e8f8c842-8d4c-4cdd-a3ee-3e6ad43bff75', 'b1832ae2-eb98-4d05-91e5-6a5da0948827', '6b12c499-4ee6-47e8-9b69-0328cad08c03', 3, 'Emergency Travel Situations', 'Situations d''urgence en voyage', '["Report lost items", "Handle travel emergencies", "Ask for police help", "Describe travel problems"]'::jsonb, '["Signaler des objets perdus", "Gérer les urgences de voyage", "Demander l''aide de la police", "Décrire les problèmes de voyage"]'::jsonb, 'Intermediate', '2025-09-28T18:13:48.42551+00:00'),
  ('cfd64367-0a50-4711-b979-3acf208dde68', '4a199f66-b0cf-40b0-b6a7-a77e400b2a50', 'd1d458e8-c945-4291-a15e-6bfe366c12c8', 4, 'Expressions of Emotion', 'Expressions d''émotion', '["Express happiness and joy", "Describe sadness and disappointment", "Show anger and frustration", "Express surprise and excitement"]'::jsonb, '["Exprimer le bonheur et la joie", "Décrire la tristesse et la déception", "Montrer la colère et la frustration", "Exprimer la surprise et l''excitation"]'::jsonb, 'Beginner', '2025-09-28T18:13:14.869158+00:00'),
  ('83b51834-fdc5-4903-a65b-fa365dba4e64', 'f6b6bc21-877c-48f8-9d89-f57f12e3394e', 'b846a053-92a3-4b46-aa5f-50ac0c7024ba', 4, 'Grocery Store (Hanout)', 'Épicerie (Hanout)', '["Shop for daily groceries", "Ask for specific products", "Understand local store terms"]'::jsonb, '["Faire ses courses quotidiennes", "Demander des produits spécifiques", "Comprendre les termes de magasin local"]'::jsonb, 'Beginner', '2025-09-28T18:12:53.086673+00:00'),
  ('666680b1-b402-4790-9d62-4b42c21f432b', '3a462949-cdb5-4ee4-bf6b-f8aa0a1f2e25', '8e4d6e59-4b0a-4ad5-bbdf-10b98f9bc011', 4, 'Forming Negatives', 'Formation des phrases négatives', '["Learn negation particles and how to negate verbs and sentences.", "Practice short negative responses and questions.", "Understand double negation or emphatic forms if present."]'::jsonb, '["Apprendre les particules de négation et comment nier des verbes et phrases.", "S’exercer aux réponses et questions négatives courtes.", "Comprendre la négation double ou les formes emphatiques si présentes."]'::jsonb, 'Beginner', '2025-09-17T12:19:51.286065+00:00'),
  ('cc166060-831b-42fe-9fba-8ee8a10dc970', '560783da-e5c0-4ae8-8036-ed4cf767a808', 'd6606da8-765d-490b-ab4c-1b0246140547', 4, 'Dentist & Oral Health', 'Dentiste et santé bucco-dentaire', '["Discuss dental problems", "Understand dental procedures", "Make dental appointments"]'::jsonb, '["Discuter des problèmes dentaires", "Comprendre les procédures dentaires", "Prendre rendez-vous chez le dentiste"]'::jsonb, 'Intermediate', '2025-09-28T18:12:31.587939+00:00'),
  ('d4ecdab0-b945-4fa5-a5d1-3270d2ab9844', '52a59643-5198-48ff-ac2f-1cf141d3bb49', '8e4d6e59-4b0a-4ad5-bbdf-10b98f9bc011', 4, 'Future Forms: Plans & Predictions', 'Formes du futur : projets et prédictions', '["Form future tense and express plans or predictions.", "Use future markers and time expressions.", "Practice making plans and arrangements in dialogues."]'::jsonb, '["Former le futur et exprimer projets ou prédictions.", "Utiliser des marqueurs du futur et des expressions temporelles.", "S’exercer à faire des projets et arrangements dans des dialogues."]'::jsonb, 'Intermediate', '2025-09-17T12:19:51.286065+00:00'),
  ('0bb241d0-5518-4dd4-8c19-d55eb082a682', '30ec7c7a-671f-4d25-b0db-a796963b8a7e', 'b846a053-92a3-4b46-aa5f-50ac0c7024ba', 4, 'Telling Time', 'Dire l’heure', '["Ask and tell time in hours and half-hours.", "Use daily time expressions (morning, afternoon, evening).", "Practice scheduling phrases (meetings, appointments)."]'::jsonb, '["Demander et dire l’heure en heures et demi-heures.", "Utiliser les expressions temporelles (matin, après-midi, soir).", "S’exercer aux phrases de planification (réunions, rendez-vous)."]'::jsonb, 'Beginner', '2025-09-17T12:19:51.286065+00:00'),
  ('2619734f-cb9d-4842-a291-964a6ea6a238', '1a18365e-9c01-4460-a342-fa982e1194df', 'd6606da8-765d-490b-ab4c-1b0246140547', 4, 'Job Interviews & Applications', 'Entretiens d''embauche et candidatures', '["Answer interview questions", "Describe qualifications", "Discuss career goals", "Handle job applications"]'::jsonb, '["Répondre aux questions d''entretien", "Décrire les qualifications", "Discuter des objectifs de carrière", "Gérer les candidatures d''emploi"]'::jsonb, 'Advanced', '2025-09-28T18:13:28.423223+00:00'),
  ('d01c3157-e15c-4f06-81cc-db048a904a65', '899b1475-038b-4364-8ec7-a7ce6b9a2c3c', 'd8725dff-4eec-4358-8ac3-8c8b0129d69a', 4, 'Folktales & Storytelling', 'Contes et narration', '["Comprehend and retell simple folktales with main events.", "Study common narrative structures and cultural morals.", "Practice performing short oral narratives."]'::jsonb, '["Comprendre et raconter des contes simples avec événements principaux.", "Étudier les structures narratives communes et les morales culturelles.", "S’exercer à donner de courtes narrations orales."]'::jsonb, 'Advanced', '2025-09-17T12:19:51.286065+00:00'),
  ('84153a5b-e0fa-416b-9da6-c27815c9bf30', 'fb91fd76-ed39-4c39-99aa-81278a36e0a0', '8e4d6e59-4b0a-4ad5-bbdf-10b98f9bc011', 4, 'Morphophonology & Derivation', 'Morphophonologie et dérivation', '["Study how tones and vowel changes affect word morphology.", "Learn common derivational patterns for nouns and verbs.", "Practice forming derived words and analyzing morphological structure."]'::jsonb, '["Étudier comment les tons et changements vocaliques affectent la morphologie.", "Apprendre les schémas dérivationnels courants pour noms et verbes.", "S’exercer à former des mots dérivés et analyser la structure morphologique."]'::jsonb, 'Advanced', '2025-09-17T12:19:51.286065+00:00'),
  ('2c748dc7-4fc7-46b2-b507-25bd2d1d6e02', '3a462949-cdb5-4ee4-bf6b-f8aa0a1f2e25', '8e4d6e59-4b0a-4ad5-bbdf-10b98f9bc011', 5, 'Forming Questions (WH & Yes/No)', 'Former des questions (WH & oui/non)', '["Practice WH-questions (who, what, where, when, why, how).", "Form yes/no questions and polite interrogative forms.", "Use question words in dialogues and short interviews."]'::jsonb, '["S’exercer aux questions WH (qui, quoi, où, quand, pourquoi, comment).", "Former des questions oui/non et des formes interrogatives polies.", "Utiliser les mots interrogatifs dans des dialogues et courtes interviews."]'::jsonb, 'Beginner', '2025-09-17T12:19:51.286065+00:00'),
  ('95689efc-0be7-4bac-ae2c-6de4b7270a99', 'fb91fd76-ed39-4c39-99aa-81278a36e0a0', '8e4d6e59-4b0a-4ad5-bbdf-10b98f9bc011', 5, 'Complex Sentences & Cohesion', 'Phrases complexes et cohésion', '["Combine multiple clauses to produce fluent extended speech.", "Use cohesive devices (pronouns, conjunctions, repetition) for flow.", "Practice retelling longer narratives and descriptions."]'::jsonb, '["Combiner plusieurs propositions pour produire un discours étendu et fluide.", "Utiliser des moyens de cohésion (pronoms, conjonctions, répétitions) pour la fluidité.", "S’exercer à raconter des récits et descriptions plus longs."]'::jsonb, 'Advanced', '2025-09-17T12:19:51.286065+00:00'),
  ('8e6bf8f2-1b1a-4464-9c73-4b157bf3ce35', '899b1475-038b-4364-8ec7-a7ce6b9a2c3c', 'd8725dff-4eec-4358-8ac3-8c8b0129d69a', 5, 'Songs, Poetry & Oral Performance', 'Chants, poésie et performance orale', '["Learn short traditional songs and their cultural context.", "Understand poetic devices and perform short pieces aloud.", "Use musical/poetic language to practice rhythm and intonation."]'::jsonb, '["Apprendre de courts chants traditionnels et leur contexte culturel.", "Comprendre les procédés poétiques et interpréter de courts morceaux à voix haute.", "Utiliser le langage musical/poétique pour pratiquer le rythme et l’intonation."]'::jsonb, 'Advanced', '2025-09-17T12:19:51.286065+00:00'),
  ('0d531d39-e932-4a29-a16c-e31adb60b542', '1a18365e-9c01-4460-a342-fa982e1194df', 'd6606da8-765d-490b-ab4c-1b0246140547', 5, 'Business & Professional Services', 'Affaires et services professionnels', '["Discuss business meetings", "Handle client interactions", "Describe professional services", "Negotiate business terms"]'::jsonb, '["Discuter des réunions d''affaires", "Gérer les interactions avec les clients", "Décrire les services professionnels", "Négocier les conditions commerciales"]'::jsonb, 'Advanced', '2025-09-28T18:13:28.423223+00:00'),
  ('0b08149d-7520-4ec6-8c79-5e3ae3c926a8', '560783da-e5c0-4ae8-8036-ed4cf767a808', 'd6606da8-765d-490b-ab4c-1b0246140547', 5, 'Medical Analysis & Lab Tests', 'Analyses médicales et tests de laboratoire', '["Understand medical tests", "Discuss lab results", "Follow medical instructions"]'::jsonb, '["Comprendre les tests médicaux", "Discuter des résultats de laboratoire", "Suivre les instructions médicales"]'::jsonb, 'Intermediate', '2025-09-28T18:12:31.587939+00:00'),
