  ('c39be6a6-2ee9-427b-82d6-5a38fde434c5', '52a59643-5198-48ff-ac2f-1cf141d3bb49', '8e4d6e59-4b0a-4ad5-bbdf-10b98f9bc011', 5, 'Imperative & Commands', 'Impératif et ordres', '["Form commands and polite requests using imperative forms.", "Use softening expressions for polite instructions.", "Practice role-play: giving directions, instructions, suggestions."]'::jsonb, '["Former des ordres et demandes polies avec l’impératif.", "Utiliser des expressions adoucissantes pour des instructions polies.", "S’exercer en jeu de rôle : donner des directions, instructions, suggestions."]'::jsonb, 'Intermediate', '2025-09-17T12:19:51.286065+00:00'),
  ('e8aa5315-270c-4e3e-8ced-6abab26728ec', '560783da-e5c0-4ae8-8036-ed4cf767a808', 'd6606da8-765d-490b-ab4c-1b0246140547', 6, 'Gynecologist & Women''s Health', 'Gynécologue et santé des femmes', '["Discuss women''s health issues", "Understand reproductive health", "Make specialist appointments"]'::jsonb, '["Discuter des problèmes de santé des femmes", "Comprendre la santé reproductive", "Prendre rendez-vous avec un spécialiste"]'::jsonb, 'Advanced', '2025-09-28T18:12:31.587939+00:00'),
  ('7606294b-876d-4bac-afa9-add8b7b14f2b', '899b1475-038b-4364-8ec7-a7ce6b9a2c3c', 'd8725dff-4eec-4358-8ac3-8c8b0129d69a', 6, 'Riddles & Playful Language', 'Devinettes et langage ludique', '["Solve and create simple linguistic riddles typical to Kabiyè tradition.", "Use metaphors and indirect description for playful language practice.", "Practice interactive riddle exchanges for fluency and creativity."]'::jsonb, '["Résoudre et créer de simples devinettes linguistiques typiques de la tradition kabiyè.", "Utiliser métaphores et descriptions indirectes pour s’exercer au langage ludique.", "Pratiquer des échanges de devinettes interactifs pour la fluidité et la créativité."]'::jsonb, 'Advanced', '2025-09-17T12:19:51.286065+00:00'),
  ('2e8bdde2-5a4f-4b6f-a149-f44ff8a8d5c3', '52a59643-5198-48ff-ac2f-1cf141d3bb49', '8e4d6e59-4b0a-4ad5-bbdf-10b98f9bc011', 6, 'Conditional & Hypotheticals', 'Conditionnel et hypothèses', '["Express hypothetical situations and conditional sentences.", "Practice if-then structures and result clauses.", "Use conditional for polite requests or speculation."]'::jsonb, '["Exprimer des situations hypothétiques et phrases conditionnelles.", "S’exercer aux structures si–alors et propositions de résultat.", "Utiliser le conditionnel pour des demandes polies ou des spéculations."]'::jsonb, 'Advanced', '2025-09-17T12:19:51.286065+00:00'),
  ('dd37604a-9c75-4bf5-abfa-19d1e53f42e6', 'f6b6bc21-877c-48f8-9d89-f57f12e3394e', 'b846a053-92a3-4b46-aa5f-50ac0c7024ba', 6, 'Furniture & Home Goods', 'Meubles et articles ménagers', '["Shop for furniture", "Discuss home decoration", "Ask about delivery and assembly"]'::jsonb, '["Acheter des meubles", "Discuter de la décoration de la maison", "Demander la livraison et l''assemblage"]'::jsonb, 'Intermediate', '2025-09-28T18:12:53.086673+00:00'),
  ('b9ce3e8f-faaa-4503-96c6-0b4e34485621', '560783da-e5c0-4ae8-8036-ed4cf767a808', 'd6606da8-765d-490b-ab4c-1b0246140547', 7, 'Pediatrician & Child Health', 'Pédiatre et santé de l''enfant', '["Discuss children''s health", "Understand pediatric care", "Describe child symptoms"]'::jsonb, '["Discuter de la santé des enfants", "Comprendre les soins pédiatriques", "Décrire les symptômes de l''enfant"]'::jsonb, 'Intermediate', '2025-09-28T18:12:31.587939+00:00'),
  ('59508afb-9806-4ce7-a8d5-c86c32a05131', '52a59643-5198-48ff-ac2f-1cf141d3bb49', '8e4d6e59-4b0a-4ad5-bbdf-10b98f9bc011', 7, 'Subjunctive & Wishes', 'Subjonctif et souhaits', '["Use subjunctive forms to express wishes, doubts, and soft commands.", "Recognize subjunctive triggers and subordinate clauses.", "Practice polite requests and hypothetical desires."]'::jsonb, '["Utiliser des formes subjonctives pour exprimer souhaits, doutes et ordres atténués.", "Reconnaître les déclencheurs du subjonctif et les subordonnées.", "S’exercer à des demandes polies et désirs hypothétiques."]'::jsonb, 'Advanced', '2025-09-17T12:19:51.286065+00:00'),
  ('09f22353-1065-46b0-9e32-c80fad4ecc74', 'f6b6bc21-877c-48f8-9d89-f57f12e3394e', 'b846a053-92a3-4b46-aa5f-50ac0c7024ba', 7, 'Pharmacy & Medications', 'Pharmacie et médicaments', '["Ask for medications", "Describe symptoms to pharmacist", "Understand prescription instructions"]'::jsonb, '["Demander des médicaments", "Décrire les symptômes au pharmacien", "Comprendre les instructions de prescription"]'::jsonb, 'Intermediate', '2025-09-28T18:12:53.086673+00:00'),
  ('bc80923b-aa3e-461b-a0f6-20df08616420', '899b1475-038b-4364-8ec7-a7ce6b9a2c3c', 'd6606da8-765d-490b-ab4c-1b0246140547', 7, 'Technology & Modern Usage', 'Technologie et usage moderne', '["Learn vocabulary for phones, internet, and social media.", "Discuss modern life situations using Kabiyè vocabulary.", "Practice short dialogues about technology and media consumption."]'::jsonb, '["Apprendre le vocabulaire pour téléphone, internet et réseaux sociaux.", "Discuter de situations de la vie moderne avec le vocabulaire kabiyè.", "S’exercer à de courts dialogues sur la technologie et la consommation médiatique."]'::jsonb, 'Advanced', '2025-09-17T12:19:51.286065+00:00'),
  ('4daaa382-a45c-4522-be90-a530c11ee991', '560783da-e5c0-4ae8-8036-ed4cf767a808', 'd6606da8-765d-490b-ab4c-1b0246140547', 8, 'Emergency & Urgent Care', 'Urgences et soins d''urgence', '["Describe emergency situations", "Call for emergency help", "Understand emergency procedures"]'::jsonb, '["Décrire les situations d''urgence", "Appeler à l''aide d''urgence", "Comprendre les procédures d''urgence"]'::jsonb, 'Intermediate', '2025-09-28T18:12:31.587939+00:00'),
  ('53143819-542f-473e-bf87-adec1f12c7a5', 'f6b6bc21-877c-48f8-9d89-f57f12e3394e', 'b846a053-92a3-4b46-aa5f-50ac0c7024ba', 8, 'Toy Store & Children''s Items', 'Magasin de jouets et articles pour enfants', '["Shop for children''s toys", "Ask about age-appropriate items", "Discuss educational toys"]'::jsonb, '["Acheter des jouets pour enfants", "Demander des articles adaptés à l''âge", "Discuter des jouets éducatifs"]'::jsonb, 'Beginner', '2025-09-28T18:12:53.086673+00:00'),
  ('49b27028-f904-4356-956d-7016beec5c08', '560783da-e5c0-4ae8-8036-ed4cf767a808', 'd6606da8-765d-490b-ab4c-1b0246140547', 9, 'Emergency Medical Phrases', 'Phrases d''urgence médicale', '["Call for emergency medical help", "Describe urgent medical situations", "Give emergency information", "Follow emergency instructions"]'::jsonb, '["Appeler à l''aide médicale d''urgence", "Décrire les situations médicales urgentes", "Donner des informations d''urgence", "Suivre les instructions d''urgence"]'::jsonb, 'Intermediate', '2025-09-28T18:13:37.373887+00:00');
INSERT INTO lesson_contents (id, lesson_id, title_en, title_fr, content_en, content_fr, examples_en, examples_fr, audio_url, image_url, has_quiz, created_at) VALUES
  ('6ae62050-6923-4839-905c-ba4409355071', '3b732d48-bba6-458e-9c86-da8414f73b69', 'Kabiye Alphabet and Sounds', 'Alphabet et Sons Kabiyè', 'The Kabiye language belongs to the Kwa group within the Niger-Congo family of languages. It is spoken by the Kabiye people in Togo and Benin. In this lesson, you will learn to recognize and pronounce the letters in the Kabiye alphabet and understand the sounds represented by each letter.
INSERT INTO lesson_activities (id, lesson_id, activity_type, position, question_en, question_fr, instructions_en, instructions_fr, data, audio_url, image_url, created_at) VALUES
  ('f09c40d0-66b4-4caf-a13d-fa4b8e5ab6ff', '3b732d48-bba6-458e-9c86-da8414f73b69', 'multiple_choice', 0, 'How is the letter "ɖ" pronounced in Kabiyè?', 'Comment se prononce la lettre "ɖ" en Kabiyè?', NULL, NULL, '{"options": {"en": ["Like ''d'' in dog", "By flicking the tongue against the palate toward the back", "Like ''th'' in the", "Like ''j'' in jump"], "fr": ["Comme ''d'' dans dog", "En claquant la langue contre le palais vers l''arrière", "Comme ''th'' dans the", "Comme ''j'' dans jump"]}, "explanation": {"en": "The letter ɖ is a special sound made by flicking the tongue against the palate toward the back of the mouth.", "fr": "La lettre ɖ est un son spécial fait en faisant claquer la langue contre le palais vers l''arrière de la bouche."}, "correct_answer": "1"}'::jsonb, NULL, NULL, '2025-10-01T18:06:15.851251+00:00'),
  ('870e41f5-a2d6-4bc2-a9a2-9b6a5fc36d12', '3b732d48-bba6-458e-9c86-da8414f73b69', 'listen_choose', 1, 'Listen and Choose the Correct Word', 'Écoutez et Choisissez le Mot Correct', 'Listen to the audio and select the word you hear', 'Écoutez l''audio et sélectionnez le mot que vous entendez', '{"word": "afà", "options": {"en": ["afà", "ábálὺ", "dɔm", "cínὲ"], "fr": ["afà", "ábálὺ", "dɔm", "cínὲ"]}, "audio_url": null, "translation": "father", "correct_answer": "0"}'::jsonb, NULL, NULL, '2025-10-01T18:06:04.937302+00:00'),
  ('daaef445-749d-45e9-b2d9-0ea31d9240d5', '3b732d48-bba6-458e-9c86-da8414f73b69', 'multiple_choice', 2, 'What does "afà" mean in English?', 'Que signifie "afà" en anglais?', NULL, NULL, '{"options": {"en": ["mother", "father", "brother", "sister"], "fr": ["mère", "père", "frère", "sœur"]}, "explanation": {"en": "afà means father in Kabiyè.", "fr": "afà signifie père en Kabiyè."}, "correct_answer": "1"}'::jsonb, NULL, NULL, '2025-10-01T18:06:15.851251+00:00'),
  ('987f4f74-374c-48ca-88fb-7abbde63f3df', '3b732d48-bba6-458e-9c86-da8414f73b69', 'match_pairs', 3, 'Match Kabiyè Words with English', 'Associer les Mots Kabiyè avec l''Anglais', 'Match each Kabiyè word with its English meaning', 'Associez chaque mot Kabiyè avec sa signification en anglais', '{"pairs": [{"left": "afà", "right": {"en": "father", "fr": "père"}}, {"left": "ábálὺ", "right": {"en": "man", "fr": "homme"}}, {"left": "dɔm", "right": {"en": "salt", "fr": "sel"}}, {"left": "cínὲ", "right": {"en": "here", "fr": "ici"}}], "question_en": "Match the Kabiyè words with their meanings", "question_fr": "Associez les mots Kabiyè à leur signification"}'::jsonb, NULL, NULL, '2025-10-01T18:06:04.937302+00:00'),
  ('b70f1d75-68ca-4d8c-a610-9f05a6f51446', '3b732d48-bba6-458e-9c86-da8414f73b69', 'multiple_choice', 4, 'The Kabiyè language belongs to which language family?', 'La langue Kabiyè appartient à quelle famille de langues?', NULL, NULL, '{"options": {"en": ["Indo-European", "Afro-Asiatic", "Niger-Congo", "Sino-Tibetan"], "fr": ["Indo-européenne", "Afro-asiatique", "Nigéro-congolaise", "Sino-tibétaine"]}, "explanation": {"en": "Kabiyè belongs to the Kwa group within the Niger-Congo family of languages.", "fr": "Le Kabiyè appartient au groupe Kwa au sein de la famille des langues Niger-Congo."}, "correct_answer": "2"}'::jsonb, NULL, NULL, '2025-10-01T18:06:15.851251+00:00'),
  ('a48e0079-19db-462a-b28e-fa286eff4bbe', '3b732d48-bba6-458e-9c86-da8414f73b69', 'order_words', 5, 'Order the Letters', 'Ordonnez les Lettres', 'Put these Kabiyè letters in alphabetical order', 'Mettez ces lettres Kabiyè dans l''ordre alphabétique', '{"words": ["mba", "kʋyɔɔ", "Mɛ"], "question_en": "Arrange the words to form: \\"I greet you\\"", "question_fr": "Arrangez les mots pour former : « Je vous salue »", "correctOrder": ["Mɛ", "kʋyɔɔ", "mba"]}'::jsonb, NULL, NULL, '2025-10-01T18:06:04.937302+00:00'),
  ('4a64ea34-aa52-46aa-a467-3228bf0e279f', '3b732d48-bba6-458e-9c86-da8414f73b69', 'multiple_choice', 6, 'What is the Kabiyè word for "sandals"?', 'Quel est le mot Kabiyè pour "sandales"?', NULL, NULL, '{"options": {"en": ["dɔm", "nátaŋgbálà", "ègɔm", "kafáɖà"], "fr": ["dɔm", "nátaŋgbálà", "ègɔm", "kafáɖà"]}, "explanation": {"en": "nátaŋgbálà is the Kabiyè word for sandals.", "fr": "nátaŋgbálà est le mot Kabiyè pour sandales."}, "correct_answer": "1"}'::jsonb, NULL, NULL, '2025-10-01T18:06:15.851251+00:00'),
  ('a350a709-b688-4286-9424-4cfec30b5780', '3b732d48-bba6-458e-9c86-da8414f73b69', 'true_false', 7, 'The digraph "gb" is found in the Kabiyè alphabet.', 'Le digramme "gb" se trouve dans l''alphabet Kabiyè.', NULL, NULL, '{"options": {"en": ["True", "False"], "fr": ["Vrai", "Faux"]}, "explanation": {"en": "Yes! Kabiyè has special digraphs like gb, kp, and mb.", "fr": "Oui! Le Kabiyè a des digrammes spéciaux comme gb, kp et mb."}, "correct_answer": "0"}'::jsonb, NULL, NULL, '2025-10-01T18:06:15.851251+00:00'),
  ('60587f37-d268-4d60-8848-199f12253771', '3b732d48-bba6-458e-9c86-da8414f73b69', 'listen_choose', 8, 'Listen and Choose the Correct Word', 'Écoutez et Choisissez le Mot Correct', 'Listen to the audio and select the word you hear', 'Écoutez l''audio et sélectionnez le mot que vous entendez', '{"word": "afà", "options": ["afà", "ábálὺ", "dɔm", "cínὲ"], "audio_url": null, "translation": "father"}'::jsonb, NULL, NULL, '2025-10-01T18:06:04.937302+00:00'),
  ('32ea7a3d-8203-4d62-9170-40de9717dc3f', '3b732d48-bba6-458e-9c86-da8414f73b69', 'match_pairs', 9, 'Match Kabiyè Words with English', 'Associer les Mots Kabiyè avec l''Anglais', 'Match each Kabiyè word with its English meaning', 'Associez chaque mot Kabiyè avec sa signification en anglais', '{"pairs": [{"left": "afà", "right": "father"}, {"left": "ábálὺ", "right": "man"}, {"left": "dɔm", "right": "salt"}, {"left": "cínὲ", "right": "here"}]}'::jsonb, NULL, NULL, '2025-10-01T18:06:04.937302+00:00'),
  ('e963fa4e-481d-4b08-979b-5b38969065bc', '3b732d48-bba6-458e-9c86-da8414f73b69', 'order_words', 10, 'Order the Letters', 'Ordonnez les Lettres', 'Put these Kabiyè letters in alphabetical order', 'Mettez ces lettres Kabiyè dans l''ordre alphabétique', '{"words": ["d", "a", "c", "b"], "correctOrder": ["a", "b", "c", "d"]}'::jsonb, NULL, NULL, '2025-10-01T18:06:04.937302+00:00'),
